import { Component, ElementRef, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { UsersService } from '../users.service';
import { Subscription } from 'rxjs';
import { Table } from 'primeng/table';
import { Users } from 'src/app/core/interfaces/users.interface';
import { ConfirmationService } from 'primeng/api';

@Component({
    selector: 'app-users-home',
    templateUrl: './users-home.component.html',
    styleUrls: ['./users-home.component.scss']
})
export class UsersHomeComponent implements OnInit, OnDestroy {
    @ViewChild('name') name: ElementRef;

    constructor(private usersService: UsersService, private confirmationService: ConfirmationService) { }

    subscriptions = new Subscription();
    users: Users[];
    userDialogVisible;
    submitted: boolean = false;
    dialogMode: string;
    loading: boolean;
    selectedUser;

    permissionOptions = [{
        name: 'Yes',
        value: 1
    }, {
        name: 'No',
        value: 0
    }]

    // on initialize lifecycle hook
    ngOnInit(): void {
        this.usersService.selectedUser.next(0)
        this.subscriptions.add(this.usersService.users.subscribe(res => {
            this.users = res;
        }))
        this.subscriptions.add(this.usersService.userDialogVisible.subscribe(res => {
            this.userDialogVisible = res;
        }))
        this.subscriptions.add(this.usersService.loading.subscribe(res => {
            this.loading = res;
        }))
        this.subscriptions.add(this.usersService.existedUsernameError.subscribe(() => {
            this.name.nativeElement.select()
            this.userForm.controls['username'].setErrors({ 'error': 'Username already exists' })
        }))
        this.subscriptions.add(this.usersService.selectedUser.subscribe(res => {
            this.selectedUser = res;
        }))
    }
    // on destroy lifecycle hook
    ngOnDestroy(): void {
        this.subscriptions.unsubscribe()
    }

    // users form
    userForm = new FormGroup({
        user_id: new FormControl(null),
        username: new FormControl(null, Validators.required),
        password: new FormControl(null),
        confirm_password: new FormControl(null),
        first_name: new FormControl(null),
        last_name: new FormControl(null),
        view_stock: new FormControl(0),
        view_reports: new FormControl(0),
        delete_invoice: new FormControl(0),
        modify_customers: new FormControl(0)
    })
    get username() {
        return this.userForm.get('username')
    }
    get password() {
        return this.userForm.get('password')
    }
    get confirm_password() {
        return this.userForm.get('confirm_password')
    }

    // open users dialog
    openUserDialog(mode: string) {
        this.dialogMode = mode;
        if (this.dialogMode == 'add') {
            this.usersService.userDialogVisible.next(true)
        } else if (this.dialogMode == 'edit') {
            this.userForm.patchValue(this.selectedUser)
            this.usersService.userDialogVisible.next(true)
        }
    }


    // submit user
    submitUser() {
        this.submitted = true;

        // if adding user
        if (this.dialogMode == 'add') {
            // add validators to password inputs
            this.userForm.controls['password'].addValidators([Validators.required]);
            this.userForm.controls['confirm_password'].addValidators([Validators.required]);
            this.userForm.controls['password'].updateValueAndValidity();
            this.userForm.controls['confirm_password'].updateValueAndValidity();
            // validate form
            if (this.userForm.valid) {
                // if passwords matches
                if (this.userForm.value.password === this.userForm.value.confirm_password) {
                    this.confirmationService.confirm({
                        key: 'users',
                        message: `Are you sure that you want to continue ?`,
                        header: 'Warning',
                        icon: 'pi pi-exclamation-triangle',
                        acceptButtonStyleClass: 'p-button-danger',
                        rejectButtonStyleClass: 'p-button-secondary',
                        defaultFocus: 'reject',
                        accept: () => {
                            this.usersService.loading.next(true)
                            this.usersService.createUser(this.userForm.value);
                        },
                        reject: () => {
                            this.submitted = false;
                        }
                    })

                } else { // if passwords didn't match
                    this.userForm.controls['password'].setErrors({ 'error': 'password didnt match!' })
                    this.userForm.controls['confirm_password'].setErrors({ 'error': 'password didnt match!' })
                }
            }

        } else { // updating user
            this.userForm.controls['password'].removeValidators([Validators.required])
            this.userForm.controls['confirm_password'].removeValidators([Validators.required])
            this.userForm.controls['password'].updateValueAndValidity();
            this.userForm.controls['confirm_password'].updateValueAndValidity();

            if (this.userForm.valid) {
                this.usersService.loading.next(true);
                this.usersService.updateUser(this.userForm.value)
            }
        }


    }

    // delete
    deleteSelectedUser() {
        this.confirmationService.confirm({
            key: 'users',
            message: `Are you sure that you want to continue ?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.usersService.deleteUser(this.selectedUser)
            }
        })
    }

    // close dialog
    closeUserDialog() {
        this.usersService.userDialogVisible.next(false)
    }


    // reset form dialog
    resetDialog() {
        this.submitted = false;
        this.usersService.userDialogVisible.next(false)
        this.userForm.reset({
            view_stock: 0,
            view_reports: 0,
            delete_invoice: 0,
            modify_customers: 0
        });
    }

    // select user event
    selectUser(event) {
        this.usersService.selectedUser.next(event.data)
    }
    // unselect user event
    unselectUser() {
        this.usersService.selectedUser.next(0)
    }
}
