import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { BehaviorSubject, Subject } from 'rxjs';
import { NotificationsService } from '../_services/notifications.service';
import { ApiService } from '../_services/api.service';
import { Users } from '../core/interfaces/users.interface';

@Injectable({
    providedIn: 'root'
})
export class UsersService {

    constructor(private http: HttpClient, private notificationService: NotificationsService, private api: ApiService) {
        this.getUsers()
    }

    private host = this.api.host;
    users = new BehaviorSubject([]);
    userDialogVisible = new BehaviorSubject<boolean>(false);
    loading = new BehaviorSubject<boolean>(false);
    existedUsernameError = new Subject<void>();
    selectedUser = new BehaviorSubject<any>(0)

    // get users
    getUsers() {
        this.http.get<any>(`${this.host}/users`).subscribe({
            next: (res) => {
                this.users.next(res);
            }, error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'users');
            }
        })
    }

    // add user
    createUser(user) {
        this.http.post<any>(`${this.host}/users`, user).subscribe({
            next: (res) => {
                this.users.next([...this.users.value, res])
                this.loading.next(false);
                this.userDialogVisible.next(false);
                this.notificationService.showSuccess('User added successfully!', 'users');
            }, error: (error: HttpErrorResponse) => {
                if (error.status == 406) {
                    this.loading.next(false)
                    this.existedUsernameError.next()
                } else {
                    this.notificationService.handleError(error.error, 'users')
                }
            }
        })
    }

    // edit user
    updateUser(user) {
        this.http.put<any>(`${this.host}/users`, user).subscribe({
            next: (res) => {
                this.userDialogVisible.next(false)
                let index = this.users.value.findIndex(x => x.user_ID === user.user_ID);
                let usersToUpdate = this.users.value;
                usersToUpdate[index] = user;
                this.users.next(usersToUpdate);
                this.selectedUser.next(user);
                this.loading.next(false);
                this.notificationService.showSuccess(res.message, 'users')
            }, error: (error: HttpErrorResponse) => {
                if (error.status == 406) {
                    this.existedUsernameError.next()
                } else {
                    this.notificationService.handleError(error.error, 'users')
                }
                this.loading.next(false)
            }
        })
    }

    // delete user
    deleteUser(user) {
        this.http.delete<any>(`${this.host}/users/${user.user_id}`).subscribe({
            next: (res) => {
                let index = this.users.value.findIndex(x => x.user_id === user.user_id);
                let usersToUpdate = this.users.value;
                usersToUpdate.splice(index, 1)
                this.users.next(usersToUpdate);
                this.notificationService.showSuccess(res.message, 'users');
            }, error: (error: HttpErrorResponse) => {
                this.notificationService.handleError(error.error, 'users')
            }
        })
    }

}
